@foreach ($assets as $media)
    @php
        $type = \AtrioTeam\DigitalHub\Assets\Support\AssetFileType::fromMedia($media);
        $isImage = $type->isImage();
        $poster = \AtrioTeam\DigitalHub\Assets\Support\AssetPreview::url($media);
        // miniatura per la griglia: thumbnail ottimizzato se c'è, altrimenti
        // l'originale per le immagini (già piccole), null per gli altri → icona
        $thumbUrl = $poster ?? ($isImage ? \AtrioTeam\DigitalHub\Assets\Support\AssetUrl::original($media) : null);
        $isSelected = in_array((string) $media->getKey(), $selectedIds, true);
        $status = $this->assetStatus($media);
    @endphp
    <div
        draggable="true"
        x-on:dragstart="$event.dataTransfer.setData('application/x-asset-media', '{{ $media->getKey() }}'); $event.dataTransfer.effectAllowed = 'move'"
        x-on:contextmenu.prevent="$dispatch('asset-media-menu', { id: '{{ $media->getKey() }}', x: $event.clientX, y: $event.clientY, failed: {{ $status?->isFailed() ? 'true' : 'false' }} })"
        @class([
            'group relative border rounded-lg overflow-hidden bg-gray-50 dark:bg-gray-800/50 flex flex-col cursor-grab active:cursor-grabbing',
            'border-gray-200 dark:border-gray-700' => ! $isSelected,
            'border-primary-500 ring-2 ring-primary-500' => $isSelected,
        ])
    >
        {{-- Checkbox selezione, in alto a sx: a comparsa all'hover, sempre visibile se selezionato --}}
        <label @class([
            'absolute top-1 left-1 z-10 flex items-center justify-center rounded bg-white/90 dark:bg-gray-900/90 shadow-sm p-1 cursor-pointer transition-opacity',
            'opacity-0 group-hover:opacity-100 focus-within:opacity-100' => ! $isSelected,
            'opacity-100' => $isSelected,
        ])>
            <input
                type="checkbox"
                wire:model.live="selectedAssetIds"
                value="{{ $media->getKey() }}"
                class="h-3 w-3 rounded border-gray-300 dark:border-gray-600 text-primary-600 focus:ring-primary-500 cursor-pointer"
            />
        </label>

        {{-- Azioni per-media via menu contestuale (tasto destro): vedi sotto. --}}

        {{-- Click sulla thumbnail: apre il pannello info (slide-over). --}}
        <div
            role="button"
            title="{{ __('digital-hub::assets.info') }}"
            x-on:click="$wire.mountAction('infoAsset', { media: '{{ $media->getKey() }}' })"
            class="relative aspect-square flex items-center justify-center bg-white dark:bg-gray-900 overflow-hidden cursor-pointer"
        >
            @if ($thumbUrl)
                <img src="{{ $thumbUrl }}" alt="{{ $media->file_name }}" class="h-full w-full object-cover" loading="lazy" />
                {{-- video: icona play in overlay sul frame --}}
                @if ($type->isVideo())
                    <span class="pointer-events-none absolute inset-0 z-10 flex items-center justify-center">
                        <span class="flex h-10 w-10 items-center justify-center rounded-full bg-black/50 text-white shadow">
                            <x-filament::icon :icon="\Filament\Support\Icons\Heroicon::Play" class="h-6 w-6 ml-0.5" />
                        </span>
                    </span>
                @endif
            @else
                <x-filament::icon :icon="$type->icon()" class="h-10 w-10 text-gray-300 dark:text-gray-600" />
            @endif

            {{-- Overlay di attesa mentre il job elabora l'asset --}}
            @if ($status?->isInProgress())
                <div class="absolute inset-0 z-20 flex flex-col items-center justify-center gap-1 bg-white/70 dark:bg-gray-900/70 backdrop-blur-[1px]">
                    <x-filament::icon :icon="\Filament\Support\Icons\Heroicon::OutlinedArrowPath" class="h-5 w-5 text-primary-500 animate-spin" />
                    <span class="text-[10px] font-medium text-gray-600 dark:text-gray-300">{{ $status->label() }}</span>
                </div>
            @endif
        </div>
        <div class="px-2 py-1.5 min-w-0">
            <p class="truncate text-xs font-medium text-gray-700 dark:text-gray-200" title="{{ $media->file_name }}">{{ $media->file_name }}</p>
            <p class="text-[11px] text-gray-400 dark:text-gray-500">{{ \Illuminate\Support\Number::fileSize((int) $media->size) }}</p>
            {{-- Elaborazione fallita: badge; "Riprocessa" è nel menu contestuale --}}
            @if ($status?->isFailed())
                <span class="mt-1 inline-flex items-center gap-1 rounded px-1.5 py-0.5 text-[10px] bg-danger-100 dark:bg-danger-950 text-danger-700 dark:text-danger-300">
                    <x-filament::icon :icon="\Filament\Support\Icons\Heroicon::OutlinedExclamationTriangle" class="h-3 w-3 shrink-0" />
                    {{ $status->label() }}
                </span>
            @endif
            {{-- Nella vista aggregata "Tutti gli asset" mostra il percorso completo --}}
            @if ($this->activeFolderId === null)
                <span class="mt-1 inline-flex items-center gap-1 max-w-full rounded px-1.5 py-0.5 text-[10px] bg-gray-100 dark:bg-gray-800 text-gray-500 dark:text-gray-400" title="{{ $this->assetFolderPath($media) ?? __('digital-hub::assets.unfiled') }}">
                    <x-filament::icon :icon="\Filament\Support\Icons\Heroicon::OutlinedFolder" class="h-3 w-3 shrink-0" />

