1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace AtrioTeam\DigitalHub\Assets\Support;
6	
7	use AtrioTeam\DigitalHub\Assets\Metadata\ExtractedMetadata;
8	use Illuminate\Database\Eloquent\Model;
9	use Illuminate\Support\Number;
10	use Spatie\MediaLibrary\MediaCollections\Models\Media;
11	
12	/**
13	 * Metadati curati/normalizzati "di base" di un asset (digital-hub 22g).
14	 *
15	 * Fonte unica delle voci mostrate sia nel pannello info dell'AssetManager
16	 * (gated, utente loggato) sia nella gallery pubblica di condivisione esterna
17	 * (`/share/{token}`). Restituisce coppie label→valore già pronte: il pannello
18	 * le avvolge in `TextEntry`, la gallery le cicla in Blade.
19	 *
20	 * Le label sono tradotte qui (namespace `digital-hub::assets`) così entrambi i
21	 * consumatori restano coerenti. La logica è model-agnostic: l'autore è risolto
22	 * dal model configurato in auth, non dal model User dell'app.
23	 */
24	class AssetSummary
25	{
26	    /**
27	     * Voci di base del media, in ordine di visualizzazione.
28	     *
29	     * La risoluzione compare solo per le immagini. Con `$includeInternal` (default
30	     * true, pannello interno) si aggiungono date e autore dell'upload; la gallery
31	     * pubblica passa `false` per non esporre identità/tempi interni.
32	     *
33	     * @return list<array{label: string, value: string}>
34	     */
35	    public static function forMedia(Media $media, bool $includeInternal = true): array
36	    {
37	        $entries = [
38	            ['label' => __('digital-hub::assets.info_name'), 'value' => (string) $media->file_name],
39	            ['label' => __('digital-hub::assets.info_type'), 'value' => (string) $media->mime_type],
40	            ['label' => __('digital-hub::assets.info_size'), 'value' => (string) Number::fileSize((int) $media->size)],
41	        ];
42	
43	        $dimensions = self::dimensions($media);
44	        if ($dimensions !== null) {
45	            $entries[] = ['label' => __('digital-hub::assets.info_dimensions'), 'value' => $dimensions];
46	        }
47	
48	        if (! $includeInternal) {
49	            return $entries;
50	        }
51	
52	        // i timestamp sono in UTC: mostrati in orario locale (Europe/Rome)
53	        $entries[] = ['label' => __('digital-hub::assets.info_created'), 'value' => (string) $media->created_at?->copy()->setTimezone('Europe/Rome')->format('d/m/Y H:i')];
54	        $entries[] = ['label' => __('digital-hub::assets.info_updated'), 'value' => (string) $media->updated_at?->copy()->setTimezone('Europe/Rome')->format('d/m/Y H:i')];
55	        $entries[] = ['label' => __('digital-hub::assets.info_uploader'), 'value' => self::uploaderName($media) ?? '—'];
56	
57	        return $entries;
58	    }
59	
60	    /**
61	     * Risoluzione "W × H px" del media se è un'immagine: da `extracted_metadata`
62	     * (blocco `common`). Fonte unica: i media pre-esistenti vanno riprocessati
63	     * (vedi `digital-hub:reprocess-assets`) per popolare la colonna. null per i
64	     * non-immagine o se le dimensioni non sono ancora state estratte.
65	     */
66	    public static function dimensions(Media $media): ?string
67	    {
68	        if (! AssetFileType::fromMedia($media)->isImage()) {
69	            return null;
70	        }
71	
72	        $common = ExtractedMetadata::common($media);
73	        $width = $common['width'] ?? null;
74	        $height = $common['height'] ?? null;
75	
76	        if (! is_numeric($width) || ! is_numeric($height)) {
77	            return null;
78	        }
79	
80	        return sprintf('%d × %d px', (int) $width, (int) $height);
81	    }
82	
83	    /**
84	     * Nome dell'autore dell'upload. Se l'utente esiste ancora (FK
85	     * `uploaded_by_id`) ne mostra il nome attuale; altrimenti ricade sullo
86	     * snapshot `uploaded_by_name` salvato all'upload. null se non tracciato
87	     * (media caricati prima di questa feature).
88	     */
89	    public static function uploaderName(Media $media): ?string
90	    {
91	        $id = $media->getAttribute('uploaded_by_id');
92	        if (is_numeric($id)) {
93	            $name = self::resolveUploader((int) $id)?->getAttribute('name');
94	            if (is_string($name) && $name !== '') {
95	                return $name;
96	            }
97	        }
98	
99	        // utente eliminato o non risolvibile: snapshot del nome
100	        $snapshot = $media->getAttribute('uploaded_by_name');
101	
102	        return is_string($snapshot) && $snapshot !== '' ? $snapshot : null;
103	    }
104	
105	    /**
106	     * Risolve l'utente autore dell'upload dal model configurato in auth (così il
107	     * core non dipende dal model User dell'app). null se non configurato/trovato.
108	     */
109	    private static function resolveUploader(int $id): ?Model
110	    {
111	        $model = config('auth.providers.users.model');
112	        if (! is_string($model) || ! class_exists($model)) {
113	            return null;
114	        }
115	
116	        /** @var class-string<Model> $model */
117	        $user = $model::query()->find($id);
118	
119	        return $user instanceof Model ? $user : null;
120	    }
121	}
