);

// Colore di sfondo dell'area contenuto (parte destra della pagina, non la
// sidebar). Gestito dalla pagina Impostazioni; override CSS su `.fi-body`,
// coperto a sinistra dalla sidebar opaca. Iniettato su tutte le pagine.
$panel->renderHook(
    PanelsRenderHook::HEAD_END,
    function (): string|HtmlString {
        $color = app(GeneralSettings::class)->content_background_color;

        if (blank($color)) {
            return '';
        }

        return new HtmlString(self::contentBackgroundStyle($color));
    },
);

// Logo del panel (topbar/brand) gestito dalla pagina Impostazioni
// (GeneralSettings). Se non impostato resta il default di Filament.
$panel
    ->brandLogo(function (): string|HtmlString|null {
        $settings = app(GeneralSettings::class);

        if (blank($settings->panel_logo_path)) {
            return null;
        }

        $url = Storage::disk('public')->url($settings->panel_logo_path);

        return new HtmlString('<img src="' . e($url) . '" alt="' . e(config('app.name')) . '">');
    })
    ->brandLogoHeight(fn (): ?string => app(GeneralSettings::class)->panel_logo_height);


// Il primary color (che determina anche il colore della voce attiva nella
// sidebar) è gestito dalla pagina Impostazioni. Va impostato qui in
// register() — non è deferibile come logo/sfondo — quindi leggiamo la
// setting con un fallback al config se il DB/settings non è disponibile
// (es. durante le migration o comandi console prima che la tabella esista).

