/**
 * Genera il blocco <style> che sovrascrive il colore di sfondo dell'area
 * contenuto (la parte destra della pagina). Agisce su `.fi-body` con
 * `!important`, così vale sia in light che in dark mode; la sidebar, opaca,
 * copre la sua porzione a sinistra.
 */
private static function contentBackgroundStyle(string $hex): string
{
    $color = e($hex);

    return '<style>
        .fi-body {
            background-color: ' . $color . ' !important;
        }
    </style>';
}

/**
 * Costruisce una stringa CSS `rgba(...)` per l'overlay della login a partire
 * dal colore esadecimale (#rgb o #rrggbb) e dall'opacità (0..1) salvati nelle
 * impostazioni. Input non validi degradano a nero/opacità clampata.
 */
private static function overlayRgba(string $hex, float $opacity): string
{
    $hex = ltrim($hex, '#');

    if (strlen($hex) === 3) {
        $hex = $hex[0] . $hex[0] . $hex[1] . $hex[1] . $hex[2] . $hex[2];
    }

